// New Products Component
// Grid display of latest products with quick actions

import React from 'react';
import { Link } from 'react-router-dom';
import { products } from '../../data/products';

export const NewProducts = () => {
  const newProducts = products.slice(4);

  return (
    <section className="new-products">
      <h2>New Products</h2>
      <div className="products-grid">
        {newProducts.map((product) => (
          <div key={product.id} className="product-card">
            <div className="product-image-wrapper">
              <Link to={`/products/${product.id}`}>
                <img src={product.image} alt={product.name} className="product-image" />
              </Link>
              <span className="discount-badge">{product.discount}</span>
              <div className="quick-actions">
                <button className="action-btn" title="Add to Cart">🛒</button>
                <button className="action-btn" title="Add to Wishlist">❤️</button>
                <Link className="action-btn" title="View Details" to={`/products/${product.id}`}>👁️</Link>
              </div>
            </div>
            <div className="product-details">
              <h3>
                <Link className="product-link" to={`/products/${product.id}`}>
                  {product.name}
                </Link>
              </h3>
              <div className="rating-section">
                <span className="stars">★★★★☆</span>
                <span className="rating-value">{product.rating}</span>
              </div>
              <div className="pricing-section">
                <span className="price">{product.price}</span>
                <span className="original-price">{product.originalPrice}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default NewProducts;
